mapper.select:
SELECT id, name, ST_AsText(geom) as geom, '${req.layer}' as layer FROM ${req.layer} WHERE deleted = 0
AND name LIKE CONCAT('%', #{req.keyword}, '%')
LIMIT #{req.pageSize} OFFSET #{req.pageNo}

SELECT r.longitude AS longitude, r.latitude AS latitude, 1 as value, 1 as weight FROM ibms_device_runtime r JOIN ibms_device d ON d.id = r.device_id WHERE r.deleted = 0
AND ( CASE WHEN r.state IN (1, 3) THEN 'online' WHEN r.state = 2 THEN 'offline' ELSE 'fault' END ) = #{req.status}
AND d.device_type_code = #{req.deviceType}
